BEGIN;
CREATE TABLE IF NOT EXISTS advisory_identities(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,email TEXT NOT NULL,password_hash TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('admin','analyst','advisor','manager')),disabled_at TIMESTAMPTZ,UNIQUE(tenant_id,email));
CREATE TABLE IF NOT EXISTS advisory_cases(id UUID PRIMARY KEY,tenant_id TEXT NOT NULL,client_token TEXT NOT NULL,status TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,owner_id TEXT NOT NULL,proposal_author_id TEXT,proposal_approver_id TEXT,intake_encrypted JSONB NOT NULL,discovery_encrypted JSONB,proposal_encrypted JSONB,encryption_key_version TEXT NOT NULL,qualification JSONB NOT NULL,provider_receipts JSONB NOT NULL DEFAULT '{}',decision_token_hash TEXT,decision_expires_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS advisory_events(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,case_id UUID NOT NULL REFERENCES advisory_cases(id),event_type TEXT NOT NULL,from_status TEXT,to_status TEXT,actor_id TEXT NOT NULL,actor_role TEXT NOT NULL,reason TEXT,correlation_id TEXT NOT NULL,details JSONB NOT NULL DEFAULT '{}',occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE OR REPLACE FUNCTION immutable_advisory_event() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'advisory event is append-only';END$$;DROP TRIGGER IF EXISTS advisory_events_immutable ON advisory_events;CREATE TRIGGER advisory_events_immutable BEFORE UPDATE OR DELETE ON advisory_events FOR EACH ROW EXECUTE FUNCTION immutable_advisory_event();
CREATE TABLE IF NOT EXISTS advisory_provider_outbox(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,case_id UUID NOT NULL REFERENCES advisory_cases(id),provider TEXT NOT NULL,operation TEXT NOT NULL,idempotency_key TEXT NOT NULL,payload_digest TEXT NOT NULL,payload_encrypted JSONB NOT NULL,encryption_key_version TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,available_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),lease_until TIMESTAMPTZ,provider_receipt TEXT,last_error TEXT,UNIQUE(provider,idempotency_key));
CREATE TABLE IF NOT EXISTS advisory_provider_events(provider TEXT NOT NULL,event_id TEXT NOT NULL,payload_digest TEXT NOT NULL,received_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(provider,event_id));
CREATE INDEX IF NOT EXISTS advisory_queue_idx ON advisory_cases(tenant_id,status,updated_at);CREATE INDEX IF NOT EXISTS advisory_outbox_idx ON advisory_provider_outbox(status,available_at);COMMIT;
